parameters.jsCode:
// Junta os trechos recuperados da base de FAQs num único item.
//
// Cópia do nó de mesmo nome do fluxo do WhatsApp (n8n/whatsapp-chatbot.json).
// Os quatro motivos de ele existir estão lá e valem igual aqui:
//
// 1. FAN-OUT. O vector store em modo "load" emite UM ITEM POR DOCUMENTO.
//    Sem esta agregação, o AI Agent rodaria uma vez por documento.
//
// 2. PERDA DE CAMPOS. A saída do vector store substitui o formato do item e
//    derruba IdChat, EventId e CorrelationId — que o sessionKey da memória e a
//    resposta HTTP precisam. Aqui eles voltam, lidos do "Dados".
//
// 3. TEXTO VAZIO. O nó devolve `pageContent: ""` (string vazia, não null) e
//    joga o documento inteiro em `metadata`. Ler com `??` não resolve, porque
//    `"" ?? x` devolve `""`.
//
// 4. RELEVÂNCIA. O vector store devolve os `topK` mais PRÓXIMOS, não os que de
//    fato respondem à pergunta. O filtro de score descarta cada trecho pela sua
//    própria relevância, antes de o agente vê-lo.
//
// A ÚNICA diferença em relação ao fluxo do WhatsApp é o `TrechosDebug`: a lista
// de TODOS os trechos que a busca devolveu, com score e com o veredito do
// filtro — inclusive os descartados. Ela não vai para o agente; vai só na
// resposta HTTP, para a tela de revisão do protótipo.
//
// É esse campo que dá sentido ao protótipo: o LIMIAR_SCORE abaixo foi estimado
// a partir de CINCO consultas manuais. Com dezenas de perguntas reais, cada uma
// com os scores registrados e um 👍/👎 do participante ao lado, ele deixa de ser
// um chute e passa a ser calibrável.

const dados = $('Dados').first().json;

// Limiar do vector search. Estimado a partir de um teste manual: consultas
// com assunto claro (zinco, farmácia popular, consulta odontológica)
// trouxeram trechos relevantes entre 0.85 e 0.93; consultas sem assunto ou
// fora de escopo ficaram em 0.75–0.79. 0.82 fica no meio, com folga para os
// dois lados. Precisa ser o MESMO valor do fluxo do WhatsApp — se divergir, o
// protótipo deixa de medir o comportamento real e vira outro produto.
const LIMIAR_SCORE = 0.82;

const trechos = [];
const debug = [];

for (const item of $input.all()) {
  const doc = item.json?.document ?? item.json ?? {};
  const meta = doc.metadata ?? {};

  // Ausência de `score` é tratada como "mantém": este filtro existe para
  // cortar por relevância, não para apagar um trecho por um motivo alheio,
  // como o nó mudar de formato de saída numa atualização futura.
  const score = typeof item.json?.score === 'number' ? item.json.score : 1;
  const passou = score >= LIMIAR_SCORE;

  // `||` e não `??`: string vazia precisa cair para a próxima fonte.
  let texto = (doc.pageContent || '').trim();

  if (!texto) {
    texto = (meta.text || '').trim();
  }

  // Última defesa: remonta o trecho a partir dos campos crus. O assunto entra
  // junto porque muitas perguntas são idênticas entre exames ("Como me
  // preparar para o Exame?") — sem ele o agente não sabe de qual exame o
  // trecho fala e pode responder sobre o exame errado.
  if (!texto && (meta.question || meta.answer)) {
    texto = [
      meta.category ? `Assunto: ${meta.category}` : null,
      meta.question ? `Pergunta: ${meta.question}` : null,
      meta.answer ? `Resposta: ${meta.answer}` : null,
    ]
      .filter(Boolean)
      .join('\n');
  }

  // Registra TODOS os trechos, inclusive os cortados — a razão de existir da
  // tela de revisão é justamente ver o que ficou de fora e por quanto.
  debug.push({
    score: Number(score.toFixed(4)),
    usado: passou && Boolean(texto),
    category: meta.category ?? null,
    question: meta.question ?? null,
    // Prévia curta: o transporte é uma resposta HTTP, não faz sentido devolver
    // dez FAQs inteiras a cada mensagem.
    previa: texto ? texto.slice(0, 240) : null,
  });

  if (passou && texto) {
    trechos.push(texto);
  }
}

const contexto = trechos
  .map((texto, i) => `[Trecho ${i + 1}]\n${texto}`)
  .join('\n\n');

return [
  {
    json: {
      ...dados,
      ContextoFaq: contexto,
      TemContexto: trechos.length > 0,
      QtdTrechos: trechos.length,
      TrechosDebug: debug,
      LimiarScore: LIMIAR_SCORE,
    },
  },
];

